//! Tests for the ZIP method 98 decoder (PPMd variant I rev. 1).
//!
//! The fixtures in `tests/fixtures/ppmd/zip98_*.dat` are bare entry data
//! (2-byte PPMd header + range-coded body) cut out of ZIPs written by
//! 7-Zip 26.03 (`7zz a -tzip -mm=PPMd -mo=N -mmem=Mm -mx=L`). Their inputs
//! are generated by [`input`] below, so only the compressed side is
//! stored. `regenerate_fixtures` (ignored) rebuilds them; the
//! `matches_7zz_*` tests compress fresh inputs with `7zz` when it is on
//! the PATH and skip otherwise.

#![cfg(feature = "ppmd")]

use compcol::ppmd::ZipDecoder;
use compcol::{Decoder as _, Error, Status};

// ─── inputs ───────────────────────────────────────────────────────────

/// Deterministic xorshift generator.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

/// Text-like input: words from a fixed random vocabulary.
fn words(seed: u64, len: usize, vocab: usize) -> Vec<u8> {
    let mut r = Rng(seed);
    let dict: Vec<Vec<u8>> = (0..vocab)
        .map(|_| {
            let n = 2 + r.below(8) as usize;
            (0..n).map(|_| b'a' + r.below(26) as u8).collect()
        })
        .collect();
    let mut out = Vec::with_capacity(len + 16);
    while out.len() < len {
        out.extend_from_slice(&dict[r.below(vocab as u64) as usize]);
        out.push(if r.below(12) == 0 { b'\n' } else { b' ' });
    }
    out.truncate(len);
    out
}

/// Mixed input: text runs, random binary, repeats and byte ramps, so every
/// context shape and the high-byte flags get exercised.
fn mixed(seed: u64, len: usize) -> Vec<u8> {
    let mut r = Rng(seed);
    let mut out = Vec::with_capacity(len + 4096);
    while out.len() < len {
        match r.below(4) {
            0 => out.extend(words(
                r.next(),
                1 + r.below(4000) as usize,
                50 + r.below(500) as usize,
            )),
            1 => {
                let n = 1 + r.below(2000);
                for _ in 0..n {
                    out.push(r.next() as u8);
                }
            }
            2 => {
                let b = r.next() as u8;
                let n = 1 + r.below(300) as usize;
                out.extend(std::iter::repeat_n(b, n));
            }
            _ => {
                let start = r.next() as u8;
                let n = 1 + r.below(1000) as usize;
                out.extend((0..n).map(|i| start.wrapping_add(i as u8)));
            }
        }
    }
    out.truncate(len);
    out
}

/// The named fixture inputs. Keep in sync with `FIXTURES`.
fn input(name: &str) -> Vec<u8> {
    match name {
        // A short input 7-Zip doesn't fall back to storing.
        "short" => b"hello hello hello hello hello hello hello".to_vec(),
        "o2_text" | "o6_text" | "o16_text" => words(1, 40_000, 400),
        "o4_m3_mixed" | "o8_mixed" => mixed(2, 30_000),
        // Order 16 in a 1 MB arena on varied input: the model runs out of
        // memory several times (restart / cut-off).
        "o16_m1_restart" | "o16_m1_cutoff" => words(3, 110_000, 30_000),
        "o10_m1_cutoff_text" => words(4, 150_000, 4000),
        _ => panic!("unknown fixture {name}"),
    }
}

/// name, 7zz -mo, -mmem (MB), -mx.
const FIXTURES: &[(&str, u32, u32, u32)] = &[
    ("short", 6, 1, 5),
    ("o2_text", 2, 1, 5),
    ("o6_text", 6, 4, 5),
    ("o16_text", 16, 16, 9),
    ("o4_m3_mixed", 4, 3, 5),
    ("o8_mixed", 8, 2, 9),
    ("o16_m1_restart", 16, 1, 5),
    ("o16_m1_cutoff", 16, 1, 9),
    ("o10_m1_cutoff_text", 10, 1, 9),
];

fn fixture(name: &str) -> Vec<u8> {
    let path = format!(
        "{}/tests/fixtures/ppmd/zip98_{name}.dat",
        env!("CARGO_MANIFEST_DIR")
    );
    std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}"))
}

// ─── helpers ──────────────────────────────────────────────────────────

/// Decode `data` feeding `in_chunk` bytes at a time into `out_chunk`-byte
/// output buffers, then `finish`.
fn decode_chunked(
    mut dec: ZipDecoder,
    data: &[u8],
    in_chunk: usize,
    out_chunk: usize,
) -> Result<Vec<u8>, Error> {
    let mut out = Vec::new();
    let mut buf = vec![0u8; out_chunk];
    let mut pos = 0usize;
    loop {
        let end = pos.saturating_add(in_chunk).min(data.len());
        let (p, st) = dec.decode(&data[pos..end], &mut buf)?;
        pos += p.consumed;
        out.extend_from_slice(&buf[..p.written]);
        match st {
            Status::StreamEnd => return Ok(out),
            Status::OutputFull => {}
            Status::InputEmpty => {
                if pos >= data.len() {
                    break;
                }
            }
        }
    }
    loop {
        let (p, st) = dec.finish(&mut buf)?;
        out.extend_from_slice(&buf[..p.written]);
        if st == Status::StreamEnd {
            return Ok(out);
        }
        assert!(p.written > 0, "finish made no progress");
    }
}

fn decode(data: &[u8], len: u64) -> Result<Vec<u8>, Error> {
    decode_chunked(ZipDecoder::new(len), data, usize::MAX, 64 * 1024)
}

/// Minimal ZIP reader: the first entry's (method, uncompressed size,
/// compressed data) from its local file header. Test-only.
fn first_entry(zip: &[u8]) -> (u16, u64, Vec<u8>) {
    let u16_at = |o: usize| u16::from_le_bytes([zip[o], zip[o + 1]]);
    let u32_at = |o: usize| u32::from_le_bytes(zip[o..o + 4].try_into().unwrap());
    assert_eq!(u32_at(0), 0x0403_4b50, "local file header signature");
    assert_eq!(u16_at(6) & 8, 0, "data descriptor not expected");
    let method = u16_at(8);
    let csize = u32_at(18) as usize;
    let usize_ = u32_at(22) as u64;
    let start = 30 + u16_at(26) as usize + u16_at(28) as usize;
    (method, usize_, zip[start..start + csize].to_vec())
}

/// Compress `data` with 7zz into a ZIP entry: (method, entry data).
/// `None` when 7zz is not available. 7-Zip stores entries that don't
/// shrink (method 0).
fn sevenzip_entry(data: &[u8], order: u32, mem_mb: u32, level: u32) -> Option<(u16, Vec<u8>)> {
    use std::process::{Command, Stdio};
    use std::sync::atomic::{AtomicU32, Ordering};
    static N: AtomicU32 = AtomicU32::new(0);

    let dir = std::env::temp_dir().join(format!(
        "compcol-ppmd-zip-{}-{}",
        std::process::id(),
        N.fetch_add(1, Ordering::Relaxed)
    ));
    std::fs::create_dir_all(&dir).unwrap();
    let src = dir.join("in.bin");
    let zip = dir.join("out.zip");
    std::fs::write(&src, data).unwrap();
    let status = Command::new("7zz")
        .arg("a")
        .arg("-tzip")
        .arg("-mm=PPMd")
        .arg(format!("-mo={order}"))
        .arg(format!("-mmem={mem_mb}m"))
        .arg(format!("-mx={level}"))
        .arg(&zip)
        .arg(&src)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    let ok = matches!(status, Ok(s) if s.success());
    let bytes = ok.then(|| std::fs::read(&zip).unwrap());
    let _ = std::fs::remove_dir_all(&dir);
    let bytes = bytes?;
    let (method, len, entry) = first_entry(&bytes);
    assert_eq!(len, data.len() as u64);
    Some((method, entry))
}

fn have_7zz() -> bool {
    std::process::Command::new("7zz")
        .arg("i")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|s| s.success())
}

// ─── fixtures ─────────────────────────────────────────────────────────

#[test]
fn fixtures_decode() {
    for &(name, order, mem, level) in FIXTURES {
        let data = fixture(name);
        let want = input(name);
        let h = u16::from_le_bytes([data[0], data[1]]);
        assert_eq!((h & 0xF) as u32 + 1, order, "{name}: order");
        // 7-Zip lowers the memory size for small inputs.
        assert!((((h >> 4) & 0xFF) as u32) < mem, "{name}: mem");
        assert_eq!((h >> 12) as u32, (level >= 7) as u32, "{name}: restore");
        let got = decode(&data, want.len() as u64).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert!(got == want, "{name}: output differs");
        // The same stream ends with 7-Zip's end marker.
        let got = decode_chunked(ZipDecoder::until_end_marker(), &data, usize::MAX, 1 << 16)
            .unwrap_or_else(|e| panic!("{name} (end marker): {e:?}"));
        assert!(got == want, "{name} (end marker): output differs");
    }
}

#[test]
fn chunked_io() {
    for name in ["o6_text", "o4_m3_mixed", "short"] {
        let data = fixture(name);
        let want = input(name);
        for (ic, oc) in [(1, 1), (1, 4096), (4096, 1), (7, 13), (300, 257)] {
            let got = decode_chunked(ZipDecoder::new(want.len() as u64), &data, ic, oc)
                .unwrap_or_else(|e| panic!("{name} {ic}/{oc}: {e:?}"));
            assert!(got == want, "{name} {ic}/{oc}");
            let got = decode_chunked(ZipDecoder::until_end_marker(), &data, ic, oc)
                .unwrap_or_else(|e| panic!("{name} {ic}/{oc} marker: {e:?}"));
            assert!(got == want, "{name} {ic}/{oc} marker");
        }
    }
}

#[test]
fn restore_fixture_chunked() {
    let data = fixture("o16_m1_cutoff");
    let want = input("o16_m1_cutoff");
    let got = decode_chunked(ZipDecoder::new(want.len() as u64), &data, 1, 3).unwrap();
    assert!(got == want);
}

#[test]
fn reset_reuses_decoder() {
    let data = fixture("o8_mixed");
    let want = input("o8_mixed");
    let mut dec = ZipDecoder::new(want.len() as u64);
    let mut out = vec![0u8; want.len() + 1];
    // Garbage after the entry data is left alone.
    let mut padded = data.clone();
    padded.extend_from_slice(&[0xAA; 1024]);
    for _ in 0..2 {
        let (p, st) = dec.decode(&padded, &mut out).unwrap();
        assert_eq!((p.written, st), (want.len(), Status::StreamEnd));
        assert!(p.consumed <= padded.len());
        assert!(out[..want.len()] == want[..]);
        dec.reset();
    }
}

#[test]
fn shorter_length_stops_early() {
    let data = fixture("o6_text");
    let want = input("o6_text");
    let got = decode(&data, 1000).unwrap();
    assert_eq!(got, want[..1000]);
}

#[test]
fn zero_length_needs_no_input() {
    assert_eq!(decode(&[], 0).unwrap(), b"");
}

#[test]
fn end_marker_before_length_is_corrupt() {
    let data = fixture("o6_text");
    let want = input("o6_text");
    assert_eq!(decode(&data, want.len() as u64 + 1), Err(Error::Corrupt));
}

#[test]
fn bad_headers() {
    // Order field 0 means order 1, below the minimum.
    assert_eq!(decode(&[0x00, 0x00, 0, 0, 0, 0], 5), Err(Error::BadHeader));
    // Restore method 3+ is undefined; 2 (freeze) is unsupported as in 7-Zip.
    assert_eq!(decode(&[0x05, 0x30, 0, 0, 0, 0], 5), Err(Error::BadHeader));
    assert_eq!(
        decode(&[0x05, 0x20, 0, 0, 0, 0], 5),
        Err(Error::Unsupported)
    );
    // All-ones range coder start can't come from an encoder.
    assert_eq!(
        decode(&[0x05, 0x00, 0xFF, 0xFF, 0xFF, 0xFF], 5),
        Err(Error::Corrupt)
    );
}

#[test]
fn truncated_input_errors() {
    let data = fixture("o4_m3_mixed");
    let want = input("o4_m3_mixed");
    for cut in [0, 1, 2, 5, 6, 100, data.len() / 2, data.len() - 9] {
        let r = decode(&data[..cut], want.len() as u64);
        assert!(r.is_err(), "cut {cut} decoded");
        let r = decode_chunked(ZipDecoder::until_end_marker(), &data[..cut], 1000, 1000);
        assert!(r.is_err(), "cut {cut} decoded (marker)");
    }
}

#[test]
fn corruption_never_panics() {
    let mut r = Rng(0x9E37_79B9_7F4A_7C15);
    for name in ["o6_text", "o16_m1_cutoff", "o8_mixed"] {
        let data = fixture(name);
        let len = input(name).len() as u64;
        for _ in 0..40 {
            let mut d = data.clone();
            for _ in 0..1 + r.below(8) {
                // Keep the header valid most of the time so the body gets hit.
                let i = 2 + r.below(d.len() as u64 - 2) as usize;
                d[i] ^= 1 << r.below(8);
            }
            let _ = decode(&d, len);
            let _ = decode_chunked(ZipDecoder::until_end_marker(), &d, 4096, 4096);
        }
    }
    // Pure noise with every header.
    for h in 0..64u16 {
        let mut d = vec![(h & 0xFF) as u8, (h >> 4) as u8 & 0x0F];
        for _ in 0..20_000 {
            d.push(r.next() as u8);
        }
        let _ = decode(&d, 50_000);
    }
}

// ─── against 7-Zip ────────────────────────────────────────────────────

/// Input size for the 7zz tests: smaller in unoptimised builds.
fn scaled(n: usize) -> usize {
    if cfg!(debug_assertions) { n / 4 } else { n }
}

fn check_7zz(data: &[u8], order: u32, mem: u32, level: u32) -> bool {
    let Some((method, entry)) = sevenzip_entry(data, order, mem, level) else {
        return false;
    };
    assert_eq!(method, 98, "7zz stored the entry");
    let got = decode(&entry, data.len() as u64)
        .unwrap_or_else(|e| panic!("o{order} m{mem} x{level} len {}: {e:?}", data.len()));
    assert!(got == data, "o{order} m{mem} x{level} len {}", data.len());
    true
}

#[test]
fn matches_7zz_orders_and_sizes() {
    if !have_7zz() {
        eprintln!("7zz not available; skipping");
        return;
    }
    let n = scaled(200_000);
    let text = words(10, n, 2000);
    let mix = mixed(11, n);
    for order in [2, 3, 4, 5, 6, 7, 8, 10, 12, 14, 16] {
        for (mem, level) in [(1, 5), (1, 9), (8, 5), (32, 9)] {
            assert!(check_7zz(&text, order, mem, level));
            assert!(check_7zz(&mix, order, mem, level));
        }
    }
}

#[test]
fn matches_7zz_memory_exhaustion() {
    if !have_7zz() {
        eprintln!("7zz not available; skipping");
        return;
    }
    // A few MB in a small arena: the model fills and restarts / cuts off
    // many times.
    let mix = mixed(20, scaled(4 << 20));
    let text = words(21, scaled(4 << 20), 20_000);
    for (order, mem) in [(16, 1), (8, 1), (12, 2), (4, 1), (2, 1)] {
        for level in [5, 9] {
            check_7zz(&mix, order, mem, level);
            check_7zz(&text, order, mem, level);
        }
    }
}

/// Rebuild `tests/fixtures/ppmd/zip98_*.dat` with 7zz:
/// `cargo test --features ppmd --test ppmd_zip -- --ignored regenerate_fixtures`.
#[test]
#[ignore]
fn regenerate_fixtures() {
    for &(name, order, mem, level) in FIXTURES {
        let (method, entry) = sevenzip_entry(&input(name), order, mem, level).expect("7zz failed");
        assert_eq!(method, 98, "{name} was stored");
        let path = format!(
            "{}/tests/fixtures/ppmd/zip98_{name}.dat",
            env!("CARGO_MANIFEST_DIR")
        );
        std::fs::write(path, entry).unwrap();
    }
}
